package io.quarkiverse.cxf;

import java.util.Map;

import org.apache.cxf.common.spi.ClassLoaderService;
import org.glassfish.jaxb.runtime.marshaller.NamespacePrefixMapper;

/**
 * A {@link NamespacePrefixMapper} for the GlassFish JAXB runtime, the only JAXB runtime supported by Quarkus.
 * <p>
 * CXF generates an equivalent class at runtime using ASM, which is not possible on Quarkus.
 * In contrast to the other classes generated by CXF, the namespace mapper class is not generated at build time either,
 * because CXF generates it only when something is marshalled.
 * Hence we use this ordinary class instead.
 */
public final class QuarkusNamespacePrefixMapper extends NamespacePrefixMapper {
    private static final String[] EMPTY_STRING_ARRAY = new String[0];

    private final Map<String, String> prefixesByNamespace;
    /*
     * Not final, because CXF sets the value reflectively after the construction,
     * see org.apache.cxf.jaxb.io.DataWriterImpl.setContextualNamespaceDecls(Object, Map)
     */
    private String[] contextualNamespaceDecls = EMPTY_STRING_ARRAY;

    /**
     * An implementation of
     * {@link ClassLoaderService#createNamespaceWrapperInstance(Class, Map)}.
     *
     * @param marshallerClass the class of the marshaller for which the mapper should be created
     * @param prefixesByNamespace a {@link Map} from namespace URIs to namespace prefixes
     * @return a new {@link QuarkusNamespacePrefixMapper} if the given {@code marshallerClass} comes from the GlassFish JAXB
     *         runtime or {@code null} otherwise
     */
    public static Object create(Class<?> marshallerClass, Map<String, String> prefixesByNamespace) {
        return marshallerClass.getName().contains("org.glassfish")
                ? new QuarkusNamespacePrefixMapper(prefixesByNamespace)
                : null;
    }

    public QuarkusNamespacePrefixMapper(Map<String, String> prefixesByNamespace) {
        this.prefixesByNamespace = prefixesByNamespace;
    }

    @Override
    public String getPreferredPrefix(String namespaceUri, String suggestion, boolean requirePrefix) {
        final String prefix = prefixesByNamespace.get(namespaceUri);
        return prefix != null ? prefix : suggestion;
    }

    /**
     * Called reflectively by {@code org.apache.cxf.jaxb.io.DataWriterImpl.setContextualNamespaceDecls(Object, Map)}.
     *
     * @param contextualNamespaceDecls prefixes and namespace URIs, see {@link #getContextualNamespaceDecls()}
     */
    public void setContextualNamespaceDecls(String[] contextualNamespaceDecls) {
        this.contextualNamespaceDecls = contextualNamespaceDecls;
    }

    @Override
    public String[] getContextualNamespaceDecls() {
        return contextualNamespaceDecls;
    }
}
